-- Talent added with a UK town/city/county (or another emirate) as their location: store the country, like the rest of the Index.
-- Only touches a location that is a single place on these lists; lists like "UK, UAE" are left alone.
UPDATE talents SET location = 'UK', region = 'UK', updated_at = now()
 WHERE deleted_at IS NULL AND lower(trim(location)) IN ('london','birmingham','manchester','liverpool','leeds','sheffield','bristol','newcastle','newcastle upon tyne','nottingham','leicester','coventry','bradford','brighton','brighton and hove','hove','oxford','cambridge','york','bath','cardiff','swansea','newport','edinburgh','glasgow','aberdeen','dundee','inverness','stirling','belfast','derry','londonderry','norwich','ipswich','exeter','plymouth','bournemouth','poole','southampton','portsmouth','reading','milton keynes','luton','northampton','peterborough','stoke','stoke-on-trent','wolverhampton','derby','hull','kingston upon hull','sunderland','middlesbrough','durham','carlisle','lancaster','preston','blackpool','bolton','salford','wigan','stockport','warrington','chester','worcester','gloucester','cheltenham','hereford','shrewsbury','telford','lincoln','canterbury','maidstone','guildford','windsor','slough','watford','st albans','chelmsford','colchester','southend','basildon','crawley','wakefield','huddersfield','harrogate','doncaster','rotherham','barnsley','lichfield','tamworth','solihull','walsall','stafford','birkenhead','wrexham','bangor','truro','torquay','swindon','salisbury','winchester','hackney','shoreditch','camden','brixton','croydon','cornwall','devon','dorset','somerset','wiltshire','hampshire','kent','surrey','sussex','east sussex','west sussex','essex','hertfordshire','bedfordshire','buckinghamshire','berkshire','oxfordshire','cambridgeshire','norfolk','suffolk','lincolnshire','nottinghamshire','derbyshire','leicestershire','warwickshire','staffordshire','shropshire','cheshire','lancashire','merseyside','greater manchester','west midlands','midlands','yorkshire','north yorkshire','south yorkshire','west yorkshire','east yorkshire','northumberland','cumbria','county durham','tyne and wear','isle of wight','jersey','guernsey','isle of man','gloucestershire','herefordshire','worcestershire','northamptonshire','rutland');
UPDATE talents SET location = 'UAE', region = 'UAE', updated_at = now()
 WHERE deleted_at IS NULL AND lower(trim(location)) IN ('sharjah','ajman','ras al khaimah','fujairah','umm al quwain','al ain');
